PRAGMA recursive_triggers=OFF; ATTACH DATABASE ':memory:' AS aux; CREATE TABLE aux.t3(e,f); INSERT INTO aux.t3 VALUES(1,2); INSERT INTO aux.t3 VALUES('hello','world'); CREATE TRIGGER aux.tr1 AFTER INSERT ON t3 BEGIN INSERT INTO t3 VALUES(new.e*2,new.f*2); END; DELETE FROM t3; INSERT INTO t3 VALUES(10,20); INSERT INTO main.result SELECT e,f FROM t3 ORDER BY rowid;